const fs=require('node:fs'),path=require('node:path');const{fixture,scalar}=require('../provider-snapshot-retention/harness.cjs');
const root=path.resolve(__dirname,'../../..'),sql=f=>fs.readFileSync(path.join(root,'supabase/operations',f),'utf8');
async function setup(){const f=await fixture({tiered:true}),{db}=f;
 await db.exec("insert into public.ar_config_targets select 'AR','IN','CYCLE_'||g,'INR','印度','Asia/Kolkata'from generate_series(1,16)g;insert into public.dashboard_platform_team_map select 'AR','IN','CYCLE_'||g,'Cycle '||g,'Synthetic team','IN','印度',true from generate_series(1,16)g");
 const targets=(await db.query("select to_jsonb(t)t from private.provider_snapshot_native_catalog()t where source='ar'order by id")).rows.map(r=>r.t);for(const t of targets)await db.query('select private.provider_snapshot_register_target($1)',[t]);
 await db.exec(fs.readFileSync(path.join(__dirname,'reader-installed.sql'),'utf8'));await db.exec(sql('storage-maintenance.sql'));await db.exec(sql('snapshot-capacity-cycle.sql'));await db.exec("set statement_timeout='5s'");
 const dates=(await db.query("select to_char((statement_timestamp()at time zone'Asia/Kolkata')::date-g,'YYYY-MM-DD')d,g from generate_series(0,6)g")).rows.map(r=>r.d);
 async function cohort(day,minute,{lane='current'}={}){const id=await scalar(db,"insert into private.provider_snapshot_cohorts(lane,local_date,cutoff,roster_token,targets,supplement_pass,status,updated_at)values($1,$2,($2::date::timestamp+$3::int*interval'1minute')at time zone'Asia/Kolkata',md5($4::jsonb::text),$4,0,'ready',clock_timestamp()-interval'2hours')returning id",[lane,day,minute,JSON.stringify(targets)]);await db.query("select set_config('test.cohort',$1,false)",[id]);await db.exec(fs.readFileSync(path.join(__dirname,'seed.sql'),'utf8'));return{id,jobs:(await db.query('select job_id from private.provider_snapshot_cohort_jobs where cohort_id=$1',[id])).rows.map(r=>r.job_id)};}
 async function move(){return scalar(db,'select private.provider_snapshot_archive_closed_storage(100)');}
 async function drainMove(){let n=0;for(let i=0;i<300;i++){const r=await move();n+=r.jobs||0;if(!r.jobs)return n;}throw Error('move not bounded');}
 const read=async(day,extra={})=>scalar(db,'select public.dashboard_admin_provider_snapshot($1)',[{version:1,platformIds:targets.map(t=>t.id),startAt:day+'T00:00:00',endAt:day+'T23:59:59',direction:'charge',status:'all',currency:'INR',components:['orders','submission','intake'],...extra}]);
 await db.exec("insert into public.dashboard_profiles values('10000000-0000-4000-8000-000000000001','owner',true,'{\"mode\":\"all\",\"countries\":[]}');insert into private.test_native_catalog select *from private.provider_snapshot_native_catalog()where source='ar';select set_config('test.actor','10000000-0000-4000-8000-000000000001',false),set_config('test.session_allowed','true',false),set_config('test.ip_allowed','true',false)");
 return{db,targets,dates,cohort,move,drainMove,read,retire:id=>scalar(db,'select private.provider_snapshot_retire_intraday($1)',[id]),gc:n=>scalar(db,'select private.provider_snapshot_gc_versions($1)',[n]),balanced:()=>scalar(db,'select private.provider_snapshot_storage_balanced()')};
}module.exports={setup,scalar,sql};
